(()=>{
const root=document.getElementById('infra-observer'),content=root.querySelector('#io-content');
const purple=[31,36,28,35,32,47,40,43,35,44,39,51,49,57,45,47,41,54,48,62,53,48,50,42];
const mint=[55,54,56,52,54,58,56,56,53,57,55,61,60,62,58,58,59,61,59,64,63,60,61,61];
const svgLine=(values,width=580,height=155)=>values.map((v,i)=>(i?'L':'M')+(42+i*(width-55)/(values.length-1)).toFixed(1)+','+(height-20-v*(height-35)/100).toFixed(1)).join(' ');
function spark(values,color){return '<svg class="mini-spark" viewBox="0 0 80 32" aria-hidden="true"><path d="'+values.map((v,i)=>(i?'L':'M')+(i*80/(values.length-1)).toFixed(1)+','+(30-v*.3).toFixed(1)).join(' ')+'" fill="none" stroke="'+color+'" stroke-width="1.8" stroke-linecap="round"/></svg>';}
function stat(label,value,delta,note,icon,vals,color){return '<section class="box"><div class="stat-label">'+label+'<span class="stat-icon">'+icon+'</span></div><div class="value">'+value+'</div>'+spark(vals,color)+'<div class="stat-bottom">'+delta+'<span>'+note+'</span></div></section>';}
function chart(){return '<svg class="resource-chart" viewBox="0 0 580 190" preserveAspectRatio="none" role="img" aria-label="模拟过去一小时主机CPU和内存百分比曲线"><defs><linearGradient id="studio-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#8072eb" stop-opacity=".16"/><stop offset="100%" stop-color="#8072eb" stop-opacity="0"/></linearGradient></defs>'+[0,25,50,75,100].map(v=>'<line class="gridline" x1="42" y1="'+(135-v*1.2)+'" x2="568" y2="'+(135-v*1.2)+'"/><text x="4" y="'+(139-v*1.2)+'">'+v+'%</text>').join('')+'<path d="'+svgLine(purple)+' L567,135 L42,135 Z" fill="url(#studio-area)"/><path d="'+svgLine(mint)+'" stroke="#59bfa8" stroke-width="2" fill="none"/><path d="'+svgLine(purple)+'" stroke="#8072eb" stroke-width="2.5" fill="none" stroke-linejoin="round"/>'+['09:00','09:15','09:30','09:45','10:00'].map((t,i)=>'<text x="'+(42+i*131)+'" y="164" text-anchor="'+(i===4?'end':i===0?'start':'middle')+'">'+t+'</text>').join('')+'</svg>';}
const deviceRows=[['linux-app-01','10.20.1.11','Linux','42','61','2 秒','正常',''],['win-ad-01','10.20.1.20','Windows','18','54','3 秒','正常',''],['pve-node-01','10.20.2.10','PVE','67','78','6 秒','正常',''],['nas-backup-01','10.20.3.15','NAS','12','38','35 秒','容量预警','warning']];
function overview(){return '<div class="page-heading"><div><h2>全局概览</h2><div class="muted">全局监控效果示意 · 下方为固定快照，新增记录请在设备与服务清单中查看。</div></div><div class="page-actions"><span class="muted"><span class="status-dot"></span>模拟快照</span><button data-action="quality">数据质量 ↗</button><button class="main" data-action="devices">查看全部设备 →</button></div></div><div class="stats">'+stat('纳管设备','128','<b>+ 8</b>','较上个演示周期','▤',[35,33,45,43,52,47,67,65,77,85],'#8a7beb')+stat('运行容器','246','<b>98.4%</b>','运行状态正常','⬡',[50,60,56,62,59,69,63,73,67,80],'#6ab8a8')+stat('待处理告警','7','<b class="warn">2 严重</b>','· 5 警告','△',[70,60,65,42,50,35,38,22,28,30],'#e9ad7a')+stat('端到端延迟 P95','6.8s','<b>达标</b>','目标 ≤ 10s · 基础指标','◎',[40,45,37,45,40,35,44,39,37,42],'#8a7beb')+'</div><div class="overview-grid"><section class="box"><div class="panel-head"><div><h3>资源使用趋势</h3><small>服务器平均值 · 最近 1 小时</small></div><div class="chart-legend"><span><i class="legend-key"></i>CPU</span><span><i class="legend-key mint"></i>内存</span></div></div>'+chart()+'<div class="chart-summary"><span>CPU 当前<b>42.0%</b></span><span>内存当前<b>61.0%</b></span><span class="badge">5 秒采样窗口</span></div></section><section class="box"><div class="panel-head"><h3>设备健康分布</h3><button class="link-button" data-action="devices">详情 ↗</button></div><div class="health-layout"><div class="health-ring"><div><strong>128</strong><small>纳管设备</small></div></div><div class="health-key"><div><span><i></i>正常</span><b>114</b></div><div><span><i style="background:#eead72"></i>需关注</span><b>8</b></div><div><span><i style="background:#cbd3e4"></i>离线 / 未知</span><b>6</b></div></div></div><div class="quality-strip"><div>有效样本率<strong>99.92%</strong></div><div>数据过期<strong>1 台</strong></div><div>时钟异常<strong>1 台</strong></div></div></section><section class="box"><div class="panel-head"><div><h3>重点设备</h3><small>生产环境 · 资源与采集状态</small></div><button class="link-button" data-action="devices">全部设备 →</button></div><div class="wrap"><table><thead><tr><th>设备名称</th><th>CPU</th><th>内存</th><th>数据年龄</th><th>状态</th></tr></thead><tbody>'+deviceRows.map((d,i)=>'<tr><td><div class="device-name"><span class="device-symbol">'+['▤','⊞','◇','▱'][i]+'</span><div>'+(i===0?'<button class="link-button" data-action="detail">'+d[0]+'</button>':d[0])+'<small>'+d[1]+' · '+d[2]+'</small></div></div></td><td>'+d[3]+'%<div class="tiny-meter"><i style="width:'+d[3]+'%"></i></div></td><td>'+d[4]+'%<div class="tiny-meter"><i style="width:'+d[4]+'%;background:#6abda9"></i></div></td><td>'+d[5]+'</td><td><span class="state '+d[7]+'">'+d[6]+'</span></td></tr>').join('')+'</tbody></table></div><div class="table-footer"><span>显示 4 / 128 台设备</span><span>按设备重要度排序</span></div></section><section class="box"><div class="panel-head"><h3>需要关注</h3><button class="link-button" data-action="alerts">全部 7 条 →</button></div><div class="incident"><span class="incident-severity">!</span><div><div class="incident-title">备份存储池空间不足</div><div class="incident-desc">nas-backup-01 · 剩余容量 8%</div><div class="incident-time">09:50 · 严重 · 企业微信已接受</div></div></div><div class="incident"><span class="incident-severity">↻</span><div><div class="incident-title">容器重启频率异常</div><div class="incident-desc">billing-worker · 10 分钟内重启 4 次</div><div class="incident-time">09:56 · 警告 · 待确认</div></div></div><div class="incident"><span class="incident-severity" style="background:var(--soft);color:var(--brand)">◷</span><div><div class="incident-title">采集数据已过期</div><div class="incident-desc">linux-batch-02 · 87 秒未收到新样本</div><div class="incident-time">09:58 · 采集异常 · 不推断资源健康</div></div></div><button style="width:100%;margin-top:12px" data-action="quality">检查数据质量 →</button></section></div>';}
let busy=false;
function enhance(){if(busy)return;busy=true;const h=content.querySelector('h2');if(h&&!content.dataset.studioTitle){const title=h.textContent;content.dataset.studioTitle=title;if(title==='全局概览')content.innerHTML=overview();else{const subtitle=h.nextElementSibling;if(subtitle&&subtitle.classList.contains('muted')){const wrap=document.createElement('div');wrap.className='page-heading';const left=document.createElement('div');h.before(wrap);left.append(h,subtitle);wrap.append(left);const status=document.createElement('div');status.className='page-actions';status.innerHTML='<span class="muted"><span class="status-dot"></span>设计预览</span>';wrap.append(status);}}root.querySelector('#studio-breadcrumb').textContent=title;if(title==='业务服务'){const lane=document.createElement('section');lane.className='box';lane.style.marginBottom='18px';lane.innerHTML='<div class="panel-head"><h3>办公系统 / 依赖关系</h3><span class="state">探测正常</span></div><div class="topology-lane"><div class="topology-node">Web 入口<small>nginx · linux-app-01</small></div><span class="muted">→</span><div class="topology-node">应用服务<small>office-api · Docker</small></div><span class="muted">→</span><div class="topology-node">数据层<small>PostgreSQL / Redis</small></div></div><div class="more-info"><span>HTTP 200 / 86ms</span><span>4 个组件</span><span>跨 3 台服务器</span><span>负责人：基础设施组</span></div>';const stat=content.querySelector('.stats');if(stat)stat.after(lane);}}busy=false;}
const obs=new MutationObserver(()=>{const h=content.querySelector('h2');if(h&&h.textContent!==content.dataset.studioTitle){delete content.dataset.studioTitle;enhance();}else if(h&&!h.closest('.page-heading')){delete content.dataset.studioTitle;enhance();}});obs.observe(content,{childList:true,subtree:true});enhance();
document.getElementById('studio-theme').addEventListener('click',()=>{document.body.classList.toggle('dark');document.getElementById('studio-theme').setAttribute('aria-label',document.body.classList.contains('dark')?'切换浅色模式':'切换深色模式');});
})();
